import { z } from "zod";
import rawGraph from "@/data/graph.json";
import type { CastMember, Film, Person } from "./types";

// Generated by precompute_credit_pairs.mjs: films and the famous people (main cast / director)
// who link them. Person screens only show films from this set, so the game needs no live TMDB calls.
const graphSchema = z.object({
  films: z.record(
    z.string(),
    z.object({
      title: z.string().min(1),
      year: z.string(),
      poster: z.string().nullable(),
      genres: z.array(z.number().int()).optional(), // TMDB genre ids; used by the hint
      people: z.array(z.object({ id: z.number().int(), role: z.enum(["cast", "director"]) })),
    }),
  ),
  people: z.record(
    z.string(),
    z.object({
      name: z.string().min(1),
      photo: z.string().nullable(),
      films: z.array(z.number().int()),
    }),
  ),
});

export type Graph = z.infer<typeof graphSchema>;

export function parseGraph(input: unknown): Graph {
  return graphSchema.parse(input);
}

export const GRAPH: Graph = parseGraph(rawGraph as unknown);

export function filmById(id: number): Film | undefined {
  const f = GRAPH.films[id];
  return f ? { id, title: f.title, year: f.year, poster: f.poster } : undefined;
}

export function personById(id: number): Person | undefined {
  const p = GRAPH.people[id];
  return p ? { id, name: p.name, photo: p.photo } : undefined;
}

/** People you can hop through from a film: director first, then cast in billing order. */
export function castOf(filmId: number): CastMember[] {
  const f = GRAPH.films[filmId];
  if (!f) return [];
  const members: CastMember[] = [];
  for (const { id, role } of f.people) {
    const person = personById(id);
    if (person) members.push({ person, role });
  }
  return members.sort((a, b) => Number(b.role === "director") - Number(a.role === "director"));
}

/** Films you can reach through a person (excluding `exceptFilmId`), newest first. */
export function filmsOf(personId: number, exceptFilmId?: number): Film[] {
  const p = GRAPH.people[personId];
  if (!p) return [];
  return p.films
    .filter((id) => id !== exceptFilmId)
    .map((id) => filmById(id))
    .filter((f): f is Film => f !== undefined)
    .sort((a, b) => b.year.localeCompare(a.year) || a.title.localeCompare(b.title));
}
